{"command": "create", "path": "/app/workspace/extract.py.new", "file_text": "import os
import re
from collections import Counter
from pathlib import Path
from PIL import Image, ImageOps
import pytesseract
from openpyxl import Workbook, load_workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT = Path("/app/workspace/stat_ocr.xlsx")

MONTHS = {
    'jan': 1, 'january': 1, 'feb': 2, 'february': 2, 'mar': 3, 'march': 3,
    'apr': 4, 'april': 4, 'may': 5, 'jun': 6, 'june': 6, 'jul': 7, 'july': 7,
    'aug': 8, 'august': 8, 'sep': 9, 'sept': 9, 'september': 9,
    'oct': 10, 'october': 10, 'nov': 11, 'november': 11, 'dec': 12, 'december': 12,
}

DATE_LABEL_RE = re.compile(r'\b(date|tarikh|tanggal)\b', re.I)

PAT_DMY = re.compile(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b')
PAT_DMY2 = re.compile(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})\b')
PAT_YMD = re.compile(r'\b(\d{4})-(\d{1,2})-(\d{1,2})\b')
PAT_DMONY = re.compile(r'\b(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-,]+(\d{2,4})\b')

AMOUNT_RE = re.compile(r'(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})')

PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
]

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE',
    'CASH TENDERED', 'EXCL', 'EXCLUDING', 'EXCLUDED', 'EXCLUSIVE',
]

PAYMENT_TENDER_RE = re.compile(
    r'\b(PAYMENT|TENDER|TENDERED|CARD|VISA|MASTERCARD|MASTER CARD|CASH|RECEIVED|ROUNDING|ROUNDED|CHANGE)\b',
    re.I,
)


def validate_date(d, m, y):
    if y < 100:
        y += 2000
    if not (1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_dates_from_text(text):
    results = []
    for line in text.split('\n'):
        has_label = bool(DATE_LABEL_RE.search(line))
        for m in PAT_YMD.finditer(line):
            iso = validate_date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
            if iso:
                results.append((iso, has_label))
        for m in PAT_DMY.finditer(line):
            iso = validate_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            if iso:
                results.append((iso, has_label))
        for m in PAT_DMY2.finditer(line):
            iso = validate_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            if iso:
                results.append((iso, has_label))
        for m in PAT_DMONY.finditer(line):
            mon = MONTHS.get(m.group(2).lower())
            if not mon:
                continue
            iso = validate_date(int(m.group(1)), mon, int(m.group(3)))
            if iso:
                results.append((iso, has_label))
    return results


def line_excluded(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def find_total_candidates(text):
    """Return (tier_index, [candidate_values_in_order]) for best tier with hits, else (None, [])."""
    lines = text.split('\n')
    upper_lines = [l.upper() for l in lines]
    for tier_idx, tier_keywords in enumerate(PRIORITY_KEYWORDS):
        candidates = []
        for i, (line, uline) in enumerate(zip(lines, upper_lines)):
            if line_excluded(uline):
                continue
            if not any(kw in uline for kw in tier_keywords):
                continue
            nums = AMOUNT_RE.findall(line)
            if nums:
                candidates.append(nums[-1].replace(',', ''))
            else:
                for j in range(i + 1, min(i + 3, len(lines))):
                    nxt_u = upper_lines[j]
                    if line_excluded(nxt_u):
                        continue
                    if PAYMENT_TENDER_RE.search(lines[j]):
                        continue
                    nxt_nums = AMOUNT_RE.findall(lines[j])
                    if nxt_nums:
                        candidates.append(nxt_nums[-1].replace(',', ''))
                    break
        if candidates:
            return tier_idx, candidates
    return None, []


def find_anchors(text):
    """Collect anchor values from subtotal/cash/change/payment lines."""
    anchors = []
    lines = text.split('\n')
    cash_val = None
    change_val = None
    for line in lines:
        uline = line.upper()
        nums = AMOUNT_RE.findall(line)
        if not nums:
            continue
        last = float(nums[-1].replace(',', ''))
        if 'SUBTOTAL' in uline or 'SUB TOTAL' in uline or 'SUB-TOTAL' in uline:
            anchors.append(last)
        if 'ROUND' in uline and ('TOTAL' in uline or 'NET' in uline or 'FINAL' in uline):
            anchors.append(last)
        if 'CASH' in uline and 'CHANGE' not in uline and 'TENDERED' not in uline:
            cash_val = last
        if 'CHANGE' in uline:
            change_val = last
        if any(w in uline for w in ['VISA', 'MASTERCARD', 'MASTER CARD']):
            anchors.append(abs(last))
    if cash_val is not None and change_val is not None:
        anchors.append(round(cash_val - change_val, 2))
    elif cash_val is not None:
        anchors.append(cash_val)
    return anchors


def select_total(all_passes_candidates, all_anchors):
    """Given list of (tier_idx, [candidates]) for each pass, pick best."""
    # Find highest-priority tier with any hit
    best_tier = None
    for ti, cands in all_passes_candidates:
        if ti is not None and (best_tier is None or ti < best_tier):
            best_tier = ti
    if best_tier is None:
        # Fallback: if >=2 anchors agree within 0.05, use that
        if len(all_anchors) >= 2:
            c = Counter(round(a, 2) for a in all_anchors)
            top = c.most_common(1)[0]
            if top[1] >= 2:
                return f"{top[0]:.2f}"
        return None
    # Collect all candidates in that tier across passes (preserve order of first occurrence)
    all_cands = []
    for ti, cands in all_passes_candidates:
        if ti == best_tier:
            all_cands.extend(cands)
    if not all_cands:
        return None

    anchor_vals = [round(a, 2) for a in all_anchors]

    def near_anchor(v):
        return any(abs(float(v) - a) <= 0.05 for a in anchor_vals)

    # If any anchor-matching candidate exists, pick most common; else all
    anchor_hits = [c for c in all_cands if near_anchor(c)]
    pool = anchor_hits if anchor_hits else all_cands

    counts = Counter(pool)
    # Pick most common; tie-break: earliest in pool
    max_c = max(counts.values())
    tied = [c for c in pool if counts[c] == max_c]
    # Preserve first-occurrence order
    seen = []
    for c in pool:
        if c in tied and c not in seen:
            seen.append(c)
    val = seen[0]
    try:
        return f"{float(val):.2f}"
    except ValueError:
        return None


def ocr_variants(img_path):
    img = Image.open(img_path)
    w, h = img.size
    g = ImageOps.autocontrast(ImageOps.grayscale(img))
    yield pytesseract.image_to_string(img)
    yield pytesseract.image_to_string(g)
    yield pytesseract.image_to_string(g.resize((w * 2, h * 2), Image.LANCZOS), config='--psm 6')
    yield pytesseract.image_to_string(img.resize((w * 2, h * 2), Image.LANCZOS))
    yield pytesseract.image_to_string(g.resize((w * 3, h * 3), Image.LANCZOS), config='--psm 6')


def process_image(img_path):
    texts = list(ocr_variants(img_path))

    # Dates
    date_results_per_pass = [extract_dates_from_text(t) for t in texts]
    labelled = [iso for lst in date_results_per_pass for (iso, lab) in lst if lab]
    date_iso = None
    if labelled:
        date_iso = Counter(labelled).most_common(1)[0][0]
    else:
        all_dates = [iso for lst in date_results_per_pass for (iso, _) in lst]
        if all_dates:
            counts = Counter(all_dates)
            top = counts.most_common(1)[0]
            date_iso = top[0]

    # Totals
    pass_results = [find_total_candidates(t) for t in texts]
    anchors = []
    for t in texts:
        anchors.extend(find_anchors(t))
    total = select_total(pass_results, anchors)

    return date_iso, total


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    rows = []
    for fn in files:
        d, t = process_image(IMG_DIR / fn)
        print(f"{fn}: date={d} total={t}")
        rows.append((fn, d, t))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in rows:
        ws.append([fn, d if d else None, t if t else None])
    wb.save(OUT)

    # Validate: coerce empty strings to None, re-save, re-check.
    wb2 = load_workbook(OUT)
    assert wb2.sheetnames == ["results"]
    ws2 = wb2["results"]
    header = [c.value for c in ws2[1]]
    assert header == ["filename", "date", "total_amount"]
    for row in ws2.iter_rows(min_row=2):
        for cell in row:
            if isinstance(cell.value, str) and cell.value.strip() == "":
                cell.value = None
    wb2.save(OUT)

    wb3 = load_workbook(OUT)
    ws3 = wb3["results"]
    data_rows = list(ws3.iter_rows(min_row=2, values_only=True))
    assert len(data_rows) == len(files)
    for fn, d, t in data_rows:
        if d is not None:
            assert re.match(r'^\d{4}-\d{2}-\d{2}$', d), f"bad date {d}"
        if t is not None:
            assert re.match(r'^\d+\.\d{2}$', t), f"bad total {t}"


if __name__ == "__main__":
    main()
"}

