def line_excluded(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def find_total_candidates(text):
    """Return (tier_index, [candidate_values_in_order]) for best tier with hits, else (None, [])."""
