    upper_lines = [l.upper() for l in lines]
    for tier_idx, tier_keywords in enumerate(PRIORITY_KEYWORDS):
        candidates = []
        for i, (line, uline) in enumerate(zip(lines, upper_lines)):
            if line_excluded(uline):
                continue
            if not any(kw in uline for kw in tier_keywords):
                continue
            nums = AMOUNT_RE.findall(line)
            if nums:
                candidates.append(nums[-1].replace(',', ''))
            else:
                for j in range(i + 1, min(i + 3, len(lines))):
                    nxt_u = upper_lines[j]
                    if line_excluded(nxt_u):
                        continue
                    if PAYMENT_TENDER_RE.search(lines[j]):
