            return tier_idx, candidates
    return None, []


def find_anchors(text):
    """Collect anchor values from subtotal/cash/change/payment lines."""
    anchors = []
    lines = text.split('\n')
    cash_val = None
    change_val = None
    for line in lines:
        uline = line.upper()
        nums = AMOUNT_RE.findall(line)
        if not nums:
            continue
        last = float(nums[-1].replace(',', ''))
        if 'SUBTOTAL' in uline or 'SUB TOTAL' in uline or 'SUB-TOTAL' in uline:
            anchors.append(last)
        if 'ROUND' in uline and ('TOTAL' in uline or 'NET' in uline or 'FINAL' in uline):
            anchors.append(last)
        if 'CASH' in uline and 'CHANGE' not in uline and 'TENDERED' not in uline:
            cash_val = last
        if 'CHANGE' in uline:
            change_val = last
        if any(w in uline for w in ['VISA', 'MASTERCARD', 'MASTER CARD']):
            anchors.append(abs(last))
