PAT_YMD = re.compile(r'\b(\d{4})-(\d{1,2})-(\d{1,2})\b')
PAT_DMONY = re.compile(r'\b(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-,]+(\d{2,4})\b')

AMOUNT_RE = re.compile(r'(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})')

PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
]

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE',
    'CASH TENDERED', 'EXCL', 'EXCLUDING', 'EXCLUDED', 'EXCLUSIVE',
]

PAYMENT_TENDER_RE = re.compile(
    r'\b(PAYMENT|TENDER|TENDERED|CARD|VISA|MASTERCARD|MASTER CARD|CASH|RECEIVED|ROUNDING|ROUNDED|CHANGE)\b',
    re.I,
)


def validate_date(d, m, y):
    if y < 100:
        y += 2000
    if not (1 <= m <= 12 and 1 <= d <= 31 and 2000 <= y <= 2099):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_dates_from_text(text):
    results = []
    for line in text.split('\n'):
        has_label = bool(DATE_LABEL_RE.search(line))
        for m in PAT_YMD.finditer(line):
            iso = validate_date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
            if iso:
                results.append((iso, has_label))
        for m in PAT_DMY.finditer(line):
            iso = validate_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            if iso:
                results.append((iso, has_label))
        for m in PAT_DMY2.finditer(line):
            iso = validate_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            if iso:
                results.append((iso, has_label))
        for m in PAT_DMONY.finditer(line):
