    anchor_hits = [c for c in all_cands if near_anchor(c)]
    pool = anchor_hits if anchor_hits else all_cands

    counts = Counter(pool)
    # Pick most common; tie-break: earliest in pool
    max_c = max(counts.values())
    tied = [c for c in pool if counts[c] == max_c]
    # Preserve first-occurrence order
    seen = []
    for c in pool:
        if c in tied and c not in seen:
            seen.append(c)
    val = seen[0]
    try:
        return f"{float(val):.2f}"
    except ValueError:
        return None


def ocr_variants(img_path):
    img = Image.open(img_path)
    w, h = img.size
    g = ImageOps.autocontrast(ImageOps.grayscale(img))
    yield pytesseract.image_to_string(img)
    yield pytesseract.image_to_string(g)
    yield pytesseract.image_to_string(g.resize((w * 2, h * 2), Image.LANCZOS), config='--psm 6')
    yield pytesseract.image_to_string(img.resize((w * 2, h * 2), Image.LANCZOS))
    yield pytesseract.image_to_string(g.resize((w * 3, h * 3), Image.LANCZOS), config='--psm 6')


def process_image(img_path):
    texts = list(ocr_variants(img_path))

    # Dates
    date_results_per_pass = [extract_dates_from_text(t) for t in texts]
    labelled = [iso for lst in date_results_per_pass for (iso, lab) in lst if lab]
    date_iso = None
    if labelled:
        date_iso = Counter(labelled).most_common(1)[0][0]
    else:
        all_dates = [iso for lst in date_results_per_pass for (iso, _) in lst]
        if all_dates:
            counts = Counter(all_dates)
            top = counts.most_common(1)[0]
            date_iso = top[0]

    # Totals
    pass_results = [find_total_candidates(t) for t in texts]
    anchors = []
    for t in texts:
        anchors.extend(find_anchors(t))
    total = select_total(pass_results, anchors)

    return date_iso, total


def main():
    files = sorted(f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png')))
    rows = []
    for fn in files:
        d, t = process_image(IMG_DIR / fn)
        print(f"{fn}: date={d} total={t}")
        rows.append((fn, d, t))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in rows:
        ws.append([fn, d if d else None, t if t else None])
    wb.save(OUT)

    # Validate: coerce empty strings to None, re-save, re-check.
    wb2 = load_workbook(OUT)
    assert wb2.sheetnames == ["results"]
    ws2 = wb2["results"]
    header = [c.value for c in ws2[1]]
    assert header == ["filename", "date", "total_amount"]
    for row in ws2.iter_rows(min_row=2):
        for cell in row:
            if isinstance(cell.value, str) and cell.value.strip() == "":
                cell.value = None
    wb2.save(OUT)

    wb3 = load_workbook(OUT)
    ws3 = wb3["results"]
    data_rows = list(ws3.iter_rows(min_row=2, values_only=True))
    assert len(data_rows) == len(files)
    for fn, d, t in data_rows:
        if d is not None:
            assert re.match(r'^\d{4}-\d{2}-\d{2}$', d), f"bad date {d}"
        if t is not None:
            assert re.match(r'^\d+\.\d{2}$', t), f"bad total {t}"


if __name__ == "__main__":
    main()
